/* Review revision 2: demo-only task, connection and material flows. */
const connectionCatalog = [
 {id:'codex',agent:'Codex',avatar:'codex',computer:'工作 Mac',workspaces:['AI 眼镜项目','日常工作'],topic:'本周讨论记录'},
 {id:'claude',agent:'Claude Code',avatar:'claude',computer:'工作 Mac',workspaces:['日常工作','AI 眼镜项目'],topic:'明日会议准备'}
];
const recordDays = new Set([3,8,12,17,19,22,23]);
const recordsOnDay = day => recordDays.has(day) ? (day===23?2:1) : 0;
function allConnections(){return [...connectionCatalog,...state.extraConnections];}
function connection(id){return allConnections().find(c=>c.id===id)||connectionCatalog[0];}
function connectionPaused(id){return !!state.connectionPauses[id];}
function enabledConnections(){return allConnections().filter(c=>!connectionPaused(c.id)).length;}
function targetText(target=state.defaultTarget){const c=connection(target.id);return `${c.agent} / ${target.workspace}`;}
function controlFor(id){return state.taskControls[id]||{phase:'running',instruction:''};}
function controlLabel(id,fallback){return ({pause_queued:'暂停请求待发送',pause_requested:'等待暂停回执',paused:'已暂停',resume_queued:'继续指示待发送',resume_requested:'等待继续回执'})[controlFor(id).phase]||fallback;}
function getTask(id=state.taskId){
 if(id.startsWith('new-')){const item=state.newTasks.find(t=>t.id===id);const c=connection(item.connectionId);return {id,title:item.text,agent:c.agent,avatar:c.avatar,computer:c.computer,workspace:item.workspace,fresh:!item.received};}
 if(id==='meeting')return {id,title:'明日会议准备',agent:'Claude Code',avatar:'claude',computer:'工作 Mac',workspace:'日常工作'};
 return {id,title:id==='done'?'汇总周三的项目进展':'整理本周的讨论记录',agent:'Codex',avatar:'codex',computer:'工作 Mac',workspace:'AI 眼镜项目',done:id==='done'};
}
function taskRow(id,title,description,status='进行中',type='file'){
 const c=controlFor(id),active=id!=='done';
 const actionText=c.phase==='running'?'暂停并指示':c.phase==='paused'?'按指示继续':'查看指示进度';
 return `<div class="task-list-item"><button class="task-row" data-action="task-detail" data-id="${id}"><span class="task-icon">${icon(type)}</span><span class="task-text"><h3>${esc(title)}</h3><p>${esc(description)}</p><span class="task-status">${controlLabel(id,status)}</span></span>${icon('chevron','chevron')}</button>${active?btn('task-control-open',actionText,'task-inline-action',`data-id="${id}"`):''}</div>`;
}
function replyProgress(){return state.replyQueued?'回复已保存在手机':!state.receipt?'等待 Agent 接收':controlFor('meeting').phase==='running'?'原任务已继续':'答案已收到 · '+controlLabel('meeting','进行中');}
function tasks(){
 let content=`<h1 class="page-title">任务</h1><button class="connection-line" data-action="connections"><span class="dot"></span><span>眼镜已连接</span><span>·</span><span>${state.offline?'手机网络已断开':enabledConnections()+' 个 Agent 在线'}</span>${icon('chevron','right')}</button>`;
 if(state.offline)content+='<div class="offline-banner">手机网络暂时不可用。回复与指示会保存在手机，等待发送。</div>';
 content+=`<div class="section-heading"><h2>${state.answered?'最近回复':'需要你决定'}${!state.answered?'<span class="count">1</span>':''}</h2>${!state.answered?'<span class="section-hint">来自正在进行的任务</span>':''}</div>`;
 if(!state.answered)content+=`<article class="question-card"><div class="source-row">${avatar()}<span class="name">Claude Code</span><span class="time">2 分钟前</span></div><h3>会议材料按哪种方式整理？</h3><p class="context">明日会议准备</p><div class="question-footer"><span class="glasses-chip">${icon('glasses')}已提醒到眼镜</span>${btn('open-question','查看并回复')}</div></article>`;
 else content+=`<button class="settled-card" data-action="receipt">${icon('check')}<span>已回复会议整理方式<small>${replyProgress()}</small></span>${icon('chevron','chevron')}</button>`;
 content+=`<section class="section-gap"><div class="filter-tabs" role="tablist" aria-label="任务状态">${[['running','进行中'],['completed','已完成'],['all','全部']].map(([v,l])=>`<button id="filter-${v}" role="tab" aria-controls="task-results" aria-selected="${state.tab===v}" data-action="filter" data-tab="${v}" class="${state.tab===v?'active':''}">${l}${v==='running'?` <span class="tab-number">${2+state.newTasks.length}</span>`:''}</button>`).join('')}</div><div id="task-results" class="task-list-panel" role="tabpanel" aria-labelledby="filter-${state.tab}">`;
 if(state.tab!=='completed'){
  state.newTasks.forEach(t=>{const c=connection(t.connectionId);content+=taskRow(t.id,t.text,c.agent+' · '+t.workspace,t.received?'进行中':'等待电脑接收','send');});
  content+=taskRow('notes','整理本周的讨论记录','Codex · 工作 Mac','进行中','book');
  content+=taskRow('meeting','明日会议准备','Claude Code · 工作 Mac',state.answered?(state.receipt?'进行中':'等待 Agent 接收'):'等待你的回复');
 }
 if(state.tab!=='running')content+=taskRow('done','汇总周三的项目进展','Codex · 今天 08:32','已完成','check');
 content+='</div></section><p class="section-footer">每个回复，都会回到发起它的原任务。</p>';
 return wrapper(content,'tasks',`<div class="new-task-dock">${btn('new-task',icon('plus')+'交给 Agent 一件事','new-task-button')}</div>`);
}
function task(){
 const t=getTask(),c=controlFor(t.id),meeting=t.id==='meeting';
 let fallback=t.done?'已完成':t.fresh?'等待电脑接收':meeting&&!state.answered?'等待你的回复':meeting&&!state.receipt?'等待 Agent 接收':'进行中';
 let summary=t.done?'已完成汇总，保留了原始讨论中的决定与待办。':t.fresh?'任务已保存，将发往所选 Agent 与工作区。':meeting?'已收集讨论记录，等待按你的要求整理会议材料。':'正在按项目归类讨论记录，提取已达成的决定与待办事项。';
 if(c.phase!=='running')summary=c.phase==='paused'?'Agent 已确认暂停。你可以修改指示，再决定何时继续。':c.phase.startsWith('pause')?'已请求暂停；收到 Agent 回执之前，任务可能仍在执行。':'已发送继续指示，等待 Agent 确认开始执行。';
 let control=c.instruction?`<div class="answer-summary"><div class="eyebrow">你追加的指示</div><p>${esc(c.instruction)}</p></div>`:'';
 if(c.phase!=='running')control+=`<div class="banner">${icon('clock')}<p><strong>${controlLabel(t.id,fallback)}</strong>${c.phase.endsWith('queued')?'手机尚未联网，指示保留在本机。':c.phase==='paused'?'暂停回执已收到，原任务与 Agent 保持不变。':'不会把指示已发送当作任务已暂停或已继续。'}</p></div>`;
 let actionsHtml=t.done?btn('home-tasks','返回任务','primary full'):c.phase==='paused'?btn('request-resume','按新指示继续','primary full')+btn('edit-instruction','修改指示','subtle-link'):c.phase!=='running'?btn('control-receipt',c.phase.endsWith('queued')?'演示联网并收到回执':c.phase.startsWith('pause')?'演示 Agent 暂停回执':'演示 Agent 继续回执','primary full'):btn('pause-instruction','暂停并追加指示','primary full');
 if(meeting&&!state.answered&&c.phase==='running')actionsHtml=btn('open-question','查看并回复','primary full')+btn('pause-instruction','暂停并追加指示','subtle-link');
 return subheader('任务详情')+`<div class="body-scroll"><div class="main-padding"><div class="source-summary">${avatar(t.avatar,true)}<div><strong>${t.agent}</strong><p>${t.computer} / ${t.workspace}</p></div></div><span class="tag">${controlLabel(t.id,fallback)}</span><h1 class="question-heading">${esc(t.title)}</h1><p class="body-copy">${summary}</p>${control}<div class="group-label">任务进展</div><div class="timeline">${timeline('任务已创建',t.fresh?'刚刚':'今天 09:20',true)}${timeline(t.fresh?'等待电脑接收':'电脑已接收',t.fresh?'等待回执':'已回到原对话',!t.fresh)}${timeline(c.phase==='paused'?'Agent 已暂停':c.phase==='running'?(t.done?'整理完成':t.fresh?'等待开始处理':'当前进展'):controlLabel(t.id,fallback),c.phase==='paused'?'可以按新指示继续':t.done?'结果已返回':t.fresh?'接收后开始处理':c.phase==='running'?'今天 09:26':'等待回执更新',c.phase==='paused'||(!t.fresh&&c.phase==='running'))}</div>${t.done?'<div class="answer-summary"><div class="eyebrow">结果摘要</div><p>已整理 3 项决定、2 项待办。下一步建议确认周五评审所需材料。</p></div>':''}</div></div><div class="bottom-action">${actionsHtml}<p>${t.done?'':c.phase==='running'?'指示只发给这条任务，不改变默认 Agent。':'演示流程，不会操作真实电脑任务。'}</p></div>`;
}
function pauseInstruction(editOnly=false){
 const c=controlFor(state.taskId),draft=state.instructionDrafts[state.taskId]??c.instruction;
 sheet(editOnly?'修改任务指示':'暂停并追加指示',`<p class="body-copy">${getTask().agent} / ${esc(getTask().title)}</p><label for="task-instruction">接下来希望怎么做<span class="optional-label">选填</span></label><textarea id="task-instruction" placeholder="例如：先停一下，改为只整理本周已确定的决定。">${esc(draft)}</textarea><p class="body-copy" style="margin-top:14px">${editOnly?'保存后仍保持暂停，点「按新指示继续」才会请求执行。':'将请求 Agent 暂停这条任务；收到暂停回执后，再由你决定继续。'}</p>`,btn(editOnly?'save-instruction':'request-pause',editOnly?'保存指示':'请求暂停','primary full'));
}
function connections(){
 return subheader('电脑连接')+`<div class="body-scroll"><div class="main-padding"><p class="body-copy" style="margin:8px 0 22px">查看连接后，可以暂停、恢复或设为默认。<br>暂停连接不会暂停电脑上正在执行的任务。</p>${allConnections().map(c=>`<div class="connection-card"><header>${avatar(c.avatar,true)}<div><h3>${c.agent}</h3><p>${c.computer}</p></div><span class="tag">${connectionPaused(c.id)?'已暂停':'在线'}</span></header><div class="source-row">${icon('folder')}<span>${c.topic}</span></div><footer><span>${state.defaultTarget.id===c.id?'默认 Agent · '+state.defaultTarget.workspace:'已登记连接'}</span>${btn('connection-detail','查看连接','',`data-id="${c.id}"`)}</footer></div>`).join('')}<div class="group-label">历史连接</div><div class="setting-group">${settingRow('clock','已到期连接','3 条','expired')}</div></div></div><div class="bottom-action">${btn('add-connection',icon('plus')+'添加电脑连接','primary full')}</div>`;
}
function connectionDetail(){const c=connection(state.connectionId),paused=connectionPaused(c.id);sheet(c.agent+' 连接',`<div class="connection-summary"><p><span>电脑</span>${c.computer}</p><p><span>当前主题</span>${c.topic}</p><p><span>连接状态</span>${paused?'已暂停':'在线'}</p><p><span>默认 Agent</span>${state.defaultTarget.id===c.id?'是':'否'}</p></div><p class="body-copy">暂停后不接收这条连接的新提醒。电脑上的任务不会因此暂停；请到任务详情操作。</p><div class="button-pair" style="margin-top:18px">${btn('toggle-connection',paused?'恢复连接':'暂停连接','secondary full')}${btn('default-from-connection','设为默认','secondary full')}</div>`);}
function defaultsSheet(){
 const d=state.defaultDraft||{...state.defaultTarget};state.defaultDraft=d;const c=connection(d.id);
 sheet('默认 Agent 与工作区',`<p class="body-copy">新委托和眼镜主动唤起使用这个目标。已有问题仍回复原任务。</p><label for="default-agent">默认 Agent</label><select id="default-agent">${allConnections().map(a=>`<option value="${a.id}" ${d.id===a.id?'selected':''}>${a.agent} / ${a.computer}${connectionPaused(a.id)?'（连接已暂停）':''}</option>`).join('')}</select><label for="default-workspace">默认工作区</label><select id="default-workspace">${c.workspaces.map(w=>`<option ${w===d.workspace?'selected':''}>${w}</option>`).join('')}</select><div class="banner">${icon('glasses')}<p>主动唤起后直接使用此目标；不可用时等待或由你切换，不自动改投其他 Agent。</p></div><p class="prototype-caption">CLI 登记设为默认的接线将在实现阶段完成。</p>`,btn('save-default','保存默认目标','primary full'));
}
function beginNewTask(){if(!state.draft){state.delegateAgent=state.defaultTarget.id;state.delegateWorkspace=state.defaultTarget.workspace;}newTask();}
function newTask(){const c=connection(state.delegateAgent),isDefault=c.id===state.defaultTarget.id&&state.delegateWorkspace===state.defaultTarget.workspace;sheet('交给 Agent',`<label for="task-draft">任务内容</label><textarea id="task-draft" placeholder="例如：结合今天的讨论，整理明天会议要点">${esc(state.draft)}</textarea><div class="target-heading"><span>${isDefault?'默认目标':'本次使用的目标'}</span>${btn('defaults-from-task','管理默认','text-button')}</div><label for="task-agent">Agent</label><select id="task-agent">${allConnections().map(a=>`<option value="${a.id}" ${c.id===a.id?'selected':''}>${a.agent} / ${a.computer}${connectionPaused(a.id)?'（已暂停）':''}</option>`).join('')}</select><label for="task-workspace">工作区</label><select id="task-workspace">${c.workspaces.map(w=>`<option ${state.delegateWorkspace===w?'selected':''}>${w}</option>`).join('')}</select><p class="prototype-caption">本次更换不会修改默认目标。</p>${connectionPaused(c.id)?'<div class="warning-copy">这条连接已暂停。请先恢复，或为本次委托选择其他目标。</div>':''}<p class="form-error" id="task-error" aria-live="polite"></p>`,btn('send-task','创建委托','primary full',connectionPaused(c.id)?'disabled':''));}
function settings(){return wrapper(`<h1 class="page-title">设置</h1><div class="device-overview"><span class="device-icon">${icon('glasses')}</span><div><h3>雷鸟 iO</h3><p>已连接 · 电量 76%</p></div></div><div class="setting-group">${settingRow('laptop','电脑连接',enabledConnections()+' 个在线','connections')}${settingRow('sparkle','默认 Agent 与工作区','设置','defaults',targetText())}${settingRow('bell','眼镜提醒',state.notice?'已开启':'已关闭','reminders')}${settingRow('cloud','资料自动同步',state.syncEnabled?'已开启':'已关闭','sync-settings')}</div><div class="group-label">更多</div><div class="setting-group">${settingRow('layers','扩展工具','','tools')}${settingRow('shield','账号与设备','','account')}${settingRow('info','关于 iO Agent','','about')}</div><div class="group-label">高级</div><div class="setting-group">${settingRow('tool','开发者选项','','developer')}</div><p class="tiny-footer">iO Agent 界面设计预览<br>沿用原厂账号与设备连接</p>`,'settings');}
function syncStatusTitle(){return !state.syncEnabled?'自动同步已关闭':state.offline?'等待网络恢复':'自动同步已开启';}
function materials(){
 const count=recordsOnDay(state.day);const rows=count?materialData.slice(0,count).map((d,i)=>`<button class="material-row" data-action="material-detail" data-id="${i}"><span class="material-icon">${icon('book')}</span><span class="material-text"><h3>${d.title}</h3><p>${d.time} · 智记 · ${d.minutes}</p><span class="sync-label">${icon(i===1&&!state.synced?'clock':'check')}${i===1&&!state.synced?(!state.syncEnabled?'待同步 · 自动同步已关闭':state.offline?'待同步 · 等待联网':'等待自动同步'):'文字已同步'}</span></span>${icon('chevron','chevron')}</button>`).join(''):`<div class="quiet-empty">${icon('file')}这一天没有记录。<br>带圆点的日期有资料可查看。</div>`;
 return wrapper(`<h1 class="page-title">资料</h1><p class="body-copy page-subtitle">让 Agent 了解你的日常。</p><div class="sync-card"><div class="sync-top"><span class="sync-icon">${icon('cloud')}</span><div><h3>${syncStatusTitle()}</h3><p>最近成功：${state.synced?'刚刚':'今天 09:38'}</p></div>${btn('sync-status','查看进度','text-button')}</div><p class="sync-schedule">${!state.syncEnabled?'新资料暂停上传，已有资料仍保留。':state.offline?'待同步资料已保存在手机，联网后自动补传。':state.synced?'当前内容已同步；新内容会自动加入队列。':'稳定文字每分钟同步 · 1 项待下次同步'}</p><div class="sync-stats"><div><strong>${state.synced?13:12}</strong><p>已同步文字</p></div><div><strong>${state.synced?0:1}</strong><p>待同步</p></div><div><strong>0</strong><p>需处理</p></div></div></div><div class="toolbar"><h3>2026 年 10 月</h3>${btn('calendar',icon('calendar')+'选日期','')}</div><div class="day-strip">${[17,18,19,20,21,22,23].map((d,i)=>`<button class="${state.day===d?'active':''}" data-action="day" data-day="${d}" aria-label="10月${d}日，${recordsOnDay(d)?'有记录':'无记录'}" aria-pressed="${state.day===d}"><small>${['六','日','一','二','三','四','五'][i]}</small>${d}<span class="day-dot" style="visibility:${recordsOnDay(d)?'visible':'hidden'}"></span></button>`).join('')}</div><div class="section-heading"><h2>${state.day===23?'今天':'10 月 '+state.day+' 日'}<span class="material-count">${count?count+' 条智记':'没有记录'}</span></h2></div>${rows}<p class="section-footer">远程原音固定保留 3 天；文字与文档继续保留。</p>`,'materials');
}
function calendarSheet(){sheet('选择日期',`<p class="body-copy">2026 年 10 月</p><div class="calendar">${['一','二','三','四','五','六','日'].map(s=>'<span class="calendar-day">'+s+'</span>').join('')}${'<span></span>'.repeat(3)}${Array.from({length:31},(_,i)=>{const d=i+1,has=recordsOnDay(d)>0;return `<button data-action="pick-day" data-day="${d}" aria-label="10月${d}日，${has?'有记录':'无记录'}" class="${state.day===d?'current':''}" ${d>23?'disabled':''}><span>${d}</span><span class="calendar-dot ${has?'has-record':''}" aria-hidden="true"></span></button>`;}).join('')}</div><p class="calendar-legend"><span class="calendar-dot has-record"></span> 有记录　　无圆点的日期暂无记录</p><p class="prototype-caption">圆点表示有资料，与是否同步无关。</p>`);}
function syncDetails(){sheet('自动同步进度',`<p class="body-copy">${syncStatusTitle()}</p><div class="connection-summary"><p><span>最近成功同步</span>${state.synced?'刚刚':'今天 09:38'}</p><p><span>下次文字同步</span>${!state.syncEnabled?'已关闭':state.offline?'网络恢复后':'预计 09:42'}</p><p><span>待同步</span>${state.synced?'0 项':'1 项'}</p></div><div class="policy-row"><strong>文字</strong><p>新生成的稳定文字自动排队，每 1 分钟合并上传。</p></div><div class="policy-row"><strong>原音</strong><p>完整片段保存后自动上传，不等待整天录音结束。</p></div><div class="policy-row"><strong>断网或后台受限</strong><p>先保存在手机，恢复后继续补传。最近成功时间只在服务器确认后更新。</p></div><p class="prototype-caption">这是新版设计的暂定节奏，尚未接入 App。</p>`,btn('sync',state.synced?'已全部同步':'立即同步','primary full',!state.syncEnabled||state.offline||state.synced?'disabled':'')+btn('sync-settings','同步设置','subtle-link'));}
function syncSettings(){sheet('资料自动同步',`<div class="setting-group">${toggleRow('syncEnabled','自动同步','自动上传新文字与原音')}</div><div class="policy-row"><strong>每分钟同步稳定文字</strong><p>原音在片段完整保存后上传；断网时保留队列。</p></div><div class="policy-row"><strong>远程原音保留 3 天</strong><p>从远程保存成功起计 72 小时。本阶段固定，不提供时长调整。</p></div><p class="body-copy" style="margin-top:14px">关闭后停止新上传，已有远程资料和本机队列保留。重新开启后继续，不会关闭 Agent 对已有资料的查询。</p><p class="prototype-caption">关闭不会延长已上传原音的到期时间。</p>`,btn('close-sheet','完成','primary full'));}
function audioState(){return state.day<=19?'expired':state.materialId===1&&!state.synced?'pending':'available';}
function exportKey(){return `${state.day}-${state.materialId}`;}
function material(){
 const d=materialData[state.materialId],audio=audioState(),saved=!!state.audioExports[exportKey()];
 const audioText=audio==='expired'?'远程原音已到期':audio==='pending'?'原音等待上传':'远程原音已保存';
 const expiry=`10 月 ${state.day+3} 日 ${state.materialId===0?'08:50':'09:42'}`;
 return subheader('智记详情')+`<div class="body-scroll"><div class="main-padding"><span class="tag">${state.materialId===1&&!state.synced?'待同步':'文字已同步'}</span><h1 class="question-heading">${d.title}</h1><p class="body-copy">10 月 ${state.day} 日 · ${d.time}</p><section class="original-audio"><header>${icon('mic')}<span><strong>${audioText}</strong><small>${audio==='available'?expiry+' 到期':audio==='pending'?'远程保存成功后开始计算 3 天':'文字仍可阅读和导出'}</small></span><span class="tag">3 天</span></header><p>原音在远程保存 72 小时。保存到手机的文件不会随远程到期删除。</p>${btn('save-audio',saved?'再次保存到手机':icon('download')+'保存原音到手机','secondary full',audio!=='available'?'disabled':'')}${saved?'<span class="saved-hint">已演示保存到手机</span>':''}</section><div class="material-body"><h3>讨论摘要</h3><p>${d.text}</p><div class="quote">${d.next}</div><h3>完整转写<span class="prototype-tag">示例</span></h3><p><span class="timestamp">08:23 · 说话人 1</span>打开后最好就知道哪件事在等我。连接和测试的信息，不用每次都铺出来。</p><p><span class="timestamp">08:24 · 说话人 2</span>可以，首页先保留待回复，其他进展做成简短列表。</p></div></div></div><div class="bottom-action"><div class="button-pair">${btn('export-document',icon('download')+'导出文档','secondary')}${btn('material-delegate',icon('plus')+'交给 Agent','primary')}</div><p>原音与文档导出为交互演示，不生成真实文件。</p></div>`;
}
function saveAudio(){if(audioState()!=='available')return;sheet('保存原音到手机',`<div class="export-file">${icon('mic')}<strong>${materialData[state.materialId].title}</strong><span>原始音频 · 保留原始格式</span></div><div class="connection-summary"><p><span>保存位置</span>手机 / 下载 / iO Agent</p></div><p class="body-copy">手机副本不受远程 3 天到期影响。此次仅演示保存流程。</p>`,btn('confirm-audio-save','保存到手机','primary full'));}
function exportDocument(){sheet('导出文档',`<p class="body-copy">${materialData[state.materialId].title}</p><div class="options" role="radiogroup" aria-label="导出格式">${[['docx','Word 文档','.docx'],['md','Markdown','.md'],['txt','纯文本','.txt']].map(([v,n,ext])=>`<button class="option ${state.exportFormat===v?'selected':''}" role="radio" aria-checked="${state.exportFormat===v}" data-action="export-format" data-format="${v}"><span class="radio"></span><span>${n}<small>${ext}</small></span></button>`).join('')}</div><div class="policy-row"><strong>包含的内容</strong><p>讨论摘要、完整转写、时间与说话人标签。原音单独保存。</p></div><p class="prototype-caption">保存位置：手机 / 下载 / iO Agent</p>`,btn('confirm-document-export','导出到手机','primary full'));}
